"""Writes docs/06 (per profile), 07 (per cohort), 08 (aggregate metrics, denominators) and representative traces from results/ and traces/."""
import json, gzip, os
H=os.path.dirname(os.path.abspath(__file__))+'/..'
M={c:json.load(open(f'{H}/results/metrics-{c}.json')) for c in 'ABC'}
f=lambda r: '—' if r is None else (f"{r['n']}/{r['d']} ({r['rate']:.0%})" if isinstance(r,dict) and r.get('rate') is not None else (f"{r['n']}/{r['d']}" if isinstance(r,dict) else str(r)))
ROWS=[('diagnosis','correctlyIdentifiedWeak','weak sub-skills identified'),('diagnosis','missedWeak','weak sub-skills missed'),('diagnosis','falseDiagnosis','false diagnoses (identified kind was strong)'),('diagnosis','misconceptionClassificationAccuracy','established misconception matches a held one'),('diagnosis','missedMisconceptions','held misconceptions (≥0.3, ≥2 opportunities) never established'),
 ('teaching','appropriate','explanations on a weak kind'),('teaching','unnecessary','explanations on a strong kind'),('teaching','repeatedIneffective','repeat of an explanation whose earlier delivery did nothing'),
 ('mastery','falseAuthoritativeClaims','authoritative "shown alone" while a competency kind is weak (visit ends)'),('mastery','journeysWithFalseAuthoritativeClaim','journeys with ≥1 false authoritative claim'),('mastery','firstClaimAlreadyFalse','first claim already false (post-hoc, review)'),('mastery','trueClaimOutlivedKnowledge','true first claim later outlived the knowledge (post-hoc)'),('mastery','falseClaimsOnVisitsWithAnswers','false claims on visits with ≥1 answer (post-hoc)'),('mastery','falseShadowClaims','E1 "independently demonstrated" while that kind is weak'),('mastery','missedCompetenceShadow','strong kind, ≥4 independent answers, not shown in E1'),('mastery','missedCompetenceAuthoritative','all kinds strong, not claimed'),('mastery','crossFamilyLeakage','authoritative claims with unsupported sub-skills (E1)'),('mastery','correctAnswerInvalidMethod','right answers whose working has a false step'),
 ('retention','checksCompleted','delayed checks due and taken'),('retention','checksFailed','delayed checks failed'),('retention','shownButNoDueDate','claimed but never given a due date'),('retention','recoveryTargeting','recovery answers of the failed check\'s kind'),('retention','crossFamilyRecovery','recoveries completed without a right answer of the failed kind'),('retention','shownSubSkillNeverSampled','shown sub-skills never sampled by a delayed check'),('retention','arrivedOnShownDateButCheckNotYetDue','returns on the shown date with the check not yet due'),
 ('efficiency','boundedJourneys','journeys ending at a bound or stall')]
def table(cols):
  out=['| Metric (numerator/denominator) | '+' | '.join(c for c,_ in cols)+' |','|---|'+'---|'*len(cols)]
  for g,k,lab in ROWS: out.append(f'| {lab} | '+' | '.join(f(m[g][k]) for _,m in cols)+' |')
  for g,k,lab in [('teaching','meanGainTaughtKinds','mean hidden gain, taught kinds'),('teaching','meanGainUntaughtKinds','mean hidden gain, untaught kinds'),('efficiency','medianQuestionsToFirstDiagnosis','median questions to first diagnosis'),('efficiency','medianQuestionsPerShownSubSkill','median questions per E1-shown sub-skill'),('efficiency','meanTeachingPerLearner','mean explanations per learner'),('efficiency','medianAttemptsPerJourney','median attempts per journey')]:
    out.append(f'| {lab} | '+' | '.join(f(m[g][k]) for _,m in cols)+' |')
  out.append('| journey ends | '+' | '.join(', '.join(f'{a} {b}' for a,b in m['ends'].items()) for _,m in cols)+' |')
  return '\n'.join(out)
hdr='Generated by `scripts/report.py` from `results/metrics-*.json` (pre-registered metrics, `src/metrics.ts`). Ground truth is the synthetic learner\'s hidden state: a simulator assumption, not a fact about real students.\n\n'
open(f'{H}/docs/07-per-cohort-results.md','w').write('# 7. Per-cohort results\n\n'+hdr+table([(f"{c} ({M[c]['journeys']})",M[c]['aggregate']) for c in 'ABC'])+'\n')
s='# 6. Per-profile results\n\n'+hdr
for c in 'ABC':
  s+=f"## Cohort {c}: {M[c]['label']}\n\n"+table([(k.split('@')[0],v) for k,v in M[c]['perProfile'].items()])+'\n\n'
open(f'{H}/docs/06-per-profile-results.md','w').write(s)
# retention questions by kind, per cohort
s='# 8. Aggregate metrics and denominators\n\n'+hdr
s+='Denominators are stated in every cell as n/d. They are never pooled across cohorts. **There is no single success rate.**\n\n'
s+='## Definitions (src/metrics.ts, pre-registered)\n\n'
s+='''- **weak(kind)**: hidden ability < 0.6, or a misconception of that kind with strength ≥ 0.3. **strong(kind)**: ability ≥ 0.9 and no misconception of that kind ≥ 0.1. The competency kinds are two-step, both-sides, brackets and modelling.
- **Diagnosis.** A kind is *identified* when OpenPath delivered an explanation of that kind, or established, resolved or contested a hypothesis on a question of that family, by the journey's end.
  - "Correctly identified" is over kinds that were weak at the start and that OpenPath asked about.
  - "False diagnosis" is over identified kinds that were strong at the start.
  - Misconception accuracy compares OpenPath's established explanations with the simulator misconceptions held at strength ≥ 0.1. Explanations outside the simulator's model (prerequisite competencies) are counted separately.
- **Teaching.** Each explanation OpenPath delivered is judged against the hidden state just before it (from the learner's own instruction log, aligned by order).
  - *appropriate* if that kind was weak; *unnecessary* if it was strong.
  - *repeated ineffective* = a re-delivery of the same explanation after an earlier delivery whose drawn outcome was "none".
- **Mastery.**
  - An authoritative *claim* is status independent, transfer or verified at a visit's end. It is *false* if any competency kind is weak in the hidden state at that moment.
  - A shadow claim is E1 "independently-demonstrated" for a kind; it is false if that kind is weak.
  - *Leakage* = a claim while E1 reports unsupported sub-skills.
  - Method disagreements are over attempts with judged working.
- **Retention.**
  - Cycles are taken from OpenPath's own retention@2 history, counting only those due before the journey's last visit.
  - Recovery targeting = independent, non-retention answers between a failed check and its recovery that share the failed retention answer's kind.
  - *Cross-family recovery* = a completed recovery with no right answer of the failed kind.
  - *Arrived too early* = a visit on the date shown on the topic page with no delayed-check question asked.
- **Bounds.** 16 visits, 120 days, 250 interactions per visit. A journey is "stalled" when OpenPath offers nothing on 3 consecutive visits (doc 9: almost always after OpenPath's own hand-over to a teacher or parent).

'''
s+='## Retention questions asked, by kind\n\n| Cohort | '+' | '.join(['two-step','both-sides','brackets','modelling'])+' |\n|---|---|---|---|---|\n'
for c in 'ABC':
  r=M[c]['aggregate']['retention']['retentionQuestionsByKind']; s+=f'| {c} | '+' | '.join(str(r.get(k,0)) for k in ['two-step','both-sides','brackets','modelling'])+' |\n'
s+='\n## Instruction outcomes drawn by the learning model (synthetic)\n\n| Cohort | full | partial | none |\n|---|---|---|---|\n'
for c in 'ABC':
  o=M[c]['aggregate']['teaching']['instructionOutcomes']; s+=f"| {c} | {o.get('full',0)} | {o.get('partial',0)} | {o.get('none',0)} |\n"
open(f'{H}/docs/08-aggregate-metrics.md','w').write(s)
# representative complete traces
os.makedirs(f'{H}/traces/representative',exist_ok=True)
A=[json.loads(l) for l in gzip.open(f'{H}/traces/A.jsonl.gz','rt')]
C=[json.loads(l) for l in gzip.open(f'{H}/traces/C.jsonl.gz','rt')]
pick={'successful-S001':next(t for t in A if t['profile'].startswith('S001') and t['end']=='retention-passed'),
 'success-after-teaching-S003':next((t for t in A if t['profile'].startswith('S003') and t['end']=='retention-passed' and any(v['openpath']['teaching'] for v in t['visits'])),None),
 'failed-false-claim-S003':next(t for t in A if t['profile'].startswith('S003') and t['end']=='stalled' and any(v['openpath']['evidence']['status'] in ('independent','transfer') for v in t['visits'])),
 'forgetting-S006':next(t for t in A if t['profile'].startswith('S006')),
 'misleading-early-success-C04':next(t for t in C if t['profile'].startswith('C04'))}
for k,t in pick.items():
  if t: json.dump(t,open(f'{H}/traces/representative/{k}.json','w'),indent=1)
print('ok',[k for k,t in pick.items() if t])
